export const getBarLegendItems = (data) => {
    if (data.datasets.length === 0) {
        return [];
    }
    const legendItems = data.datasets.map((dataset, index) => ({
        color: typeof dataset.borderColor === "string" ? dataset.borderColor : "",
        text: dataset.label || "",
        value: undefined,
        index: index,
        hidden: false
    }));
    return legendItems;
};
